export function getCreatorDossier(query?: string): CreatorDossier {
  if (!query) return CREATOR_DOSSIERS['ali_abdaal'] || Object.values(CREATOR_DOSSIERS)[0];
  const q = query.toLowerCase().replace(/[^a-z0-9]/g, '_');
  for (const [key, dossier] of Object.entries(CREATOR_DOSSIERS)) {
    if (key.includes(q) || q.includes(key) || dossier.name.toLowerCase().includes(query.toLowerCase())) {
      return dossier;
    }
  }
  return CREATOR_DOSSIERS['ali_abdaal'] || Object.values(CREATOR_DOSSIERS)[0];
}
